"use strict";
// group_course/lib is the canonical source. Other function lib directories are
// generated deployment copies; run this script after every backend change.
const fs = require("fs");
const path = require("path");
const root = path.resolve(__dirname, "../cloudfunctions");
const source = path.join(root, "group_course/lib");
const check = process.argv.includes("--check");
const marker =
  "// GENERATED by scripts/build-group-course.js; edit group_course/lib instead.\n";
for (const name of [
  "group_course_payment_callback",
  "group_course_refund_callback",
  "group_course_maintenance",
]) {
  const dest = path.join(root, name, "lib");
  if (!check) fs.mkdirSync(dest, { recursive: true });
  for (const file of fs.readdirSync(source)) {
    const expected = marker + fs.readFileSync(path.join(source, file), "utf8");
    const target = path.join(dest, file);
    if (check) {
      if (
        !fs.existsSync(target) ||
        fs.readFileSync(target, "utf8") !== expected
      )
        throw Error("Stale generated module: " + target);
    } else fs.writeFileSync(target, expected);
  }
}
console.log(
  check
    ? "Group course deployment modules are consistent."
    : "Built group course deployment modules.",
);
